import json,urllib.request
url='http://127.0.0.1:8545'
def rpc(method,params=[]):
 r=urllib.request.Request(url,data=json.dumps({'jsonrpc':'2.0','id':1,'method':method,'params':params}).encode(),headers={'Content-Type':'application/json'})
 v=json.load(urllib.request.urlopen(r,timeout=5))
 if 'error' in v or 'result' not in v: raise ValueError('RPC failed: '+method)
 return v['result']
try:
 chain=int(rpc('eth_chainId'),16); genesis=rpc('eth_getBlockByNumber',['0x0',False]); actual=str(genesis['hash']).lower(); expected='0x683713729fcb72be6f3d8b88c8cda3e10569d73b9640d3bf6f5184d94bd97616'; checks={'chainId':chain==1337,'genesis':actual==expected}
 print(json.dumps({'ready':all(checks.values()),'checks':checks,'chainId':chain,'expectedChainId':1337,'genesisHash':actual,'expectedGenesisHash':expected,'rpc':url}))
except Exception as error:
 print(json.dumps({'ready':False,'error':str(error),'rpc':url}))
